<?php require_once __DIR__ . '/partials.php'; require_admin(); $services = get_services(false); admin_header('Services'); ?>
<?php if ($message = flash('success')): ?><div class="alert success"><?= e($message) ?></div><?php endif; ?>
<section class="panel"><div class="panel-head"><h2>Service pricing</h2><a class="admin-btn" href="service-form.php">Add Service</a></div><table><thead><tr><th>Name</th><th>Description</th><th>Price</th><th>Active</th><th>Actions</th></tr></thead><tbody><?php foreach ($services as $service): ?><tr><td><?= e($service['name']) ?></td><td><?= e($service['description']) ?></td><td><?= money($service['price']) ?></td><td><?= !empty($service['is_active']) ? 'Yes' : 'No' ?></td><td><a href="service-form.php?id=<?= (int) $service['id'] ?>">Edit</a><form class="inline" action="../actions/delete-service.php" method="post" onsubmit="return confirm('Delete this service?')"><input type="hidden" name="id" value="<?= (int) $service['id'] ?>"><button>Delete</button></form></td></tr><?php endforeach; ?></tbody></table></section>
<?php admin_footer(); ?>
